            page.getByText("ACTIVE", new Page.GetByTextOptions().setExact(true)).click();
            page.keyboard().press("Escape");
            page.waitForTimeout(1000);
            System.out.println("PROBE status summary=" + page.getByText("Showing").first().textContent()
                    + " url=" + page.url());

            page.getByPlaceholder("Filter by name").fill("");
            page.waitForTimeout(1000);
            System.out.println("PROBE cleared url=" + page.url());

            browser.close();
        }
    }
