+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.Collection;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * Which customers a query asks for.
+ *
+ * <p>A customer matches when it satisfies both parts:
+ * <ul>
+ *   <li>every name term is a substring of the customer's first name or last
+ *       name, ignoring case and accents;</li>
+ *   <li>the customer's status is one of {@link #statuses()}, or no status was
+ *       given at all.</li>
+ * </ul>
+ *
+ * @param nameTerms normalized name terms, as produced by {@link #of}; empty matches every name
+ * @param statuses  statuses to keep; empty keeps every status
+ */
+public record CustomerFilter(List<String> nameTerms, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter(List.of(), Set.of());
+
+    public CustomerFilter {
+        nameTerms = List.copyOf(nameTerms);
+        statuses = Set.copyOf(statuses);
+    }
+
+    /**
+     * Builds a filter from what a user typed.
+     *
+     * @param name     free text; split on whitespace into terms, blank matches every name
+     * @param statuses selected statuses; empty keeps every status
+     */
+    public static CustomerFilter of(String name, Collection<CustomerStatus> statuses) {
+        return new CustomerFilter(termsOf(name), Set.copyOf(statuses));
+    }
+
+    /** Whether {@code customer} satisfies this filter. */
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        if (nameTerms.isEmpty()) {
+            return true;
+        }
+        String firstName = normalize(customer.firstName());
+        String lastName = normalize(customer.lastName());
+        return nameTerms.stream()
+                .allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    private static List<String> termsOf(String name) {
+        String text = normalize(name).strip();
+        if (text.isEmpty()) {
+            return List.of();
+        }
+        return Arrays.asList(text.split("\\s+"));
+    }
+
+    /** Lower-cases {@code text} and strips accents, so {@code Mäkinen} becomes {@code makinen}. */
+    static String normalize(String text) {
+        return Normalizer.normalize(text, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+}
